  // PLOTLY CHART THEME HELPER
  // ---------------------------------------------------------------------------
  function getPlotlyLayoutTheme() {
    const isDark = (state.theme === 'dark');
    return {
      paper_bgcolor: 'rgba(0,0,0,0)',
      plot_bgcolor: 'rgba(0,0,0,0)',
      font: {
        family: 'Plus Jakarta Sans, sans-serif',
        color: isDark ? '#CBD5E1' : '#334155',
        size: 11
      },
      xaxis: {
        gridcolor: isDark ? 'rgba(255, 255, 255, 0.08)' : 'rgba(0, 0, 0, 0.06)',
        linecolor: isDark ? 'rgba(255, 255, 255, 0.12)' : 'rgba(0, 0, 0, 0.1)',
        tickfont: { color: isDark ? '#94A3B8' : '#64748B' }
      },
      yaxis: {
        gridcolor: isDark ? 'rgba(255, 255, 255, 0.08)' : 'rgba(0, 0, 0, 0.06)',
        linecolor: isDark ? 'rgba(255, 255, 255, 0.12)' : 'rgba(0, 0, 0, 0.1)',
        tickfont: { color: isDark ? '#94A3B8' : '#64748B' }
      },
      margin: { l: 50, r: 25, t: 30, b: 40 },
      hoverlabel: {
        bgcolor: isDark ? '#131C31' : '#FFFFFF',
        font: { color: isDark ? '#FFFFFF' : '#0F172A', family: 'Plus Jakarta Sans' }
      }
    };
  }

  // ---------------------------------------------------------------------------
  // VIEW 1: EXECUTIVE COCKPIT CHARTS
  // ---------------------------------------------------------------------------
  function renderCockpitCharts() {
    if (!state.stats) return;
    const isDark = (state.theme === 'dark');
    const baseLayout = getPlotlyLayoutTheme();

    // 1. Transaction Volume Trend (Monthly)
    const trendContainer = document.getElementById('chartMonthlyTrend');
    if (trendContainer && state.stats.monthly_trend) {
      const months = state.stats.monthly_trend.map(d => d.Month);
      const counts = state.stats.monthly_trend.map(d => d.Count);

      const trace = {
        x: months,
        y: counts,
        type: 'scatter',
        mode: 'lines+markers',
        name: 'Validated Transactions',
        line: {
          color: isDark ? '#00E5FF' : '#0284C7',
          width: 3.5,
          shape: 'spline'
        },
        marker: {
          color: '#6366F1',
          size: 7,
          line: { color: isDark ? '#00E5FF' : '#0284C7', width: 2 }
        },
        fill: 'tozeroy',
        fillcolor: isDark ? 'rgba(0, 229, 255, 0.12)' : 'rgba(2, 132, 199, 0.12)',
        hovertemplate: '<b>%{x}</b><br>Volume: %{y:,} records<extra></extra>'
      };

      const layout = {
        ...baseLayout,
        height: 360,
        xaxis: { ...baseLayout.xaxis, title: { text: 'Billing Horizon', font: { size: 12 } } },
        yaxis: { ...baseLayout.yaxis, title: { text: 'Volume (Transactions)', font: { size: 12 } } },
        hovermode: 'x unified'
      };

      Plotly.newPlot(trendContainer, [trace], layout, { responsive: true, displayModeBar: false });
    }

    // 2. Data Completeness Health Gauge
    const gaugeContainer = document.getElementById('chartCompletenessGauge');
    if (gaugeContainer) {
      const completenessVal = state.stats.completeness || 94.99;
      const barColor = completenessVal >= 95 ? (isDark ? '#00E5FF' : '#0284C7') : '#F59E0B';

      const gaugeTrace = {
        type: 'indicator',
        mode: 'gauge+number',
        value: completenessVal,
        number: {
          suffix: '%',
          font: { family: 'Outfit, sans-serif', size: 38, color: isDark ? '#FFFFFF' : '#0F172A', weight: 800 }
        },
        gauge: {
          axis: { range: [80, 100], tickwidth: 1, tickcolor: isDark ? '#64748B' : '#CBD5E1' },
          bar: { color: barColor, thickness: 0.28 },
          bgcolor: isDark ? 'rgba(255, 255, 255, 0.05)' : 'rgba(0, 0, 0, 0.05)',
          borderwidth: 0,
          steps: [
            { range: [80, 90], color: isDark ? 'rgba(239, 68, 68, 0.15)' : 'rgba(239, 68, 68, 0.1)' },
            { range: [90, 95], color: isDark ? 'rgba(245, 158, 11, 0.15)' : 'rgba(245, 158, 11, 0.1)' },
            { range: [95, 100], color: isDark ? 'rgba(16, 185, 129, 0.15)' : 'rgba(16, 185, 129, 0.1)' }
          ],
          threshold: {
            line: { color: '#E11D48', width: 3 },
            thickness: 0.8,
            value: 95.0
          }
        }
      };

      const gaugeLayout = {
        ...baseLayout,
        height: 360,
        margin: { l: 20, r: 20, t: 25, b: 20 }
      };

      Plotly.newPlot(gaugeContainer, [gaugeTrace], gaugeLayout, { responsive: true, displayModeBar: false });
    }

    // 3. Business Segment Market Share Donut
    const segmentContainer = document.getElementById('chartSegmentShare');
    if (segmentContainer && state.stats.segments) {
      const labels = Object.keys(state.stats.segments);
      const values = Object.values(state.stats.segments);

      const pieTrace = {
        type: 'pie',
        labels: labels,
        values: values,
        hole: 0.55,
        marker: {
          colors: isDark
            ? ['#00E5FF', '#6366F1', '#10B981', '#F59E0B', '#EC4899', '#8B5CF6']
            : ['#0284C7', '#6366F1', '#10B981', '#D97706', '#E11D48', '#8B5CF6'],
          line: { color: isDark ? '#0A0E1A' : '#FFFFFF', width: 2 }
        },
        textinfo: 'label+percent',
        textposition: 'auto',
        hoverinfo: 'label+value+percent'
      };

      const pieLayout = {
        ...baseLayout,
        height: 340,
        showlegend: true,
        legend: { orientation: 'h', y: -0.15, x: 0.1 }
      };

      Plotly.newPlot(segmentContainer, [pieTrace], pieLayout, { responsive: true, displayModeBar: false });
    }

    // 4. Regional Branch Bar Chart
    const branchContainer = document.getElementById('chartBranchBar');
    if (branchContainer && state.stats.branches) {
      const branchNames = Object.keys(state.stats.branches);
      const branchCounts = Object.values(state.stats.branches);

      const barTrace = {
        type: 'bar',
        x: branchNames,
        y: branchCounts,
        marker: {
          color: branchCounts,
          colorscale: isDark
            ? [[0, '#1E3A8A'], [0.5, '#00E5FF'], [1, '#6366F1']]
            : [[0, '#0369A1'], [0.5, '#38BDF8'], [1, '#6366F1']],
          line: { color: isDark ? 'rgba(255,255,255,0.15)' : 'rgba(0,0,0,0.05)', width: 1 }
        },
        text: branchCounts.map(v => v.toLocaleString()),
        textposition: 'auto',
        hovertemplate: '<b>Branch: %{x}</b><br>Volume: %{y:,} txns<extra></extra>'
      };

      const barLayout = {
        ...baseLayout,
        height: 340,
        xaxis: { ...baseLayout.xaxis, title: { text: 'Regional Branch Code' } },
        yaxis: { ...baseLayout.yaxis, title: { text: 'Transactions' } }
      };

      Plotly.newPlot(branchContainer, [barTrace], barLayout, { responsive: true, displayModeBar: false });
    }
  }

  // ---------------------------------------------------------------------------
  // VIEW 2: AI DEMAND FORECASTING STUDIO
  // ---------------------------------------------------------------------------
  // ---------------------------------------------------------------------------
  // VIEW 2: AI DEMAND FORECASTING STUDIO
  // ---------------------------------------------------------------------------
  function initForecastControls() {
    function populateSkuDropdown() {
      const forecastSkuSelect = document.getElementById('forecastSkuSelect');
      if (!forecastSkuSelect) return;

      let skuList = [];
      if (state.realForecastData && state.realForecastData.branch_skus) {
        const bCode = state.selectedBranch || 'MAA';
        const bInfo = state.realForecastData.branch_skus[bCode] || state.realForecastData.branch_skus['ALL'];
        if (state.selectedSkuScope === 'branch') {
          skuList = (bInfo && bInfo.top_10_branch) ? bInfo.top_10_branch : [];
        } else if (state.selectedSkuScope === 'overall') {
          skuList = (bInfo && bInfo.top_10_overall) ? bInfo.top_10_overall : [];
        } else {
          skuList = (bInfo && bInfo.all_skus) ? bInfo.all_skus : [];
        }
      }

      if (skuList.length > 0) {
        forecastSkuSelect.innerHTML = skuList.map(s =>
          `<option value="${s.sku}">${s.sku} (${s.volume.toLocaleString()} units)</option>`
        ).join('');
        const exists = skuList.some(s => s.sku === state.selectedSku);
        if (!exists) {
          state.selectedSku = skuList[0].sku;
        }
        forecastSkuSelect.value = state.selectedSku;
      } else {
        forecastSkuSelect.innerHTML = '<option value="RL50UV16U2">RL50UV16U2 (24,834 units)</option>';
        state.selectedSku = 'RL50UV16U2';
      }
    }

    function updateBranchBadge() {
      const branchDemandShare = document.getElementById('branchDemandShare');
      if (!branchDemandShare) return;
      if (state.realForecastData && state.realForecastData.branch_meta) {
        const meta = state.realForecastData.branch_meta[state.selectedBranch] || state.realForecastData.branch_meta['ALL'];
        branchDemandShare.textContent = `${meta.volume.toLocaleString()} units (${meta.share.toFixed(1)}%)`;
      } else {
        branchDemandShare.textContent = state.selectedBranch === 'MAA' ? '258,123 units (35.4%)' : '729,297 units (100.0%)';
      }
    }

    // 1. Regional Branch Horizon Selector
    const forecastBranchSelect = document.getElementById('forecastBranchSelect');
    if (forecastBranchSelect) {
      forecastBranchSelect.value = state.selectedBranch;
      forecastBranchSelect.addEventListener('change', () => {
        state.selectedBranch = forecastBranchSelect.value;
        updateBranchBadge();
        populateSkuDropdown();
        updateForecastStudio();
      });
    }

    // 2. SKU Scope Radio Buttons
    const skuScopeBtns = document.querySelectorAll('#skuScopeGroup .segmented-radio-btn');
    skuScopeBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        skuScopeBtns.forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        state.selectedSkuScope = btn.getAttribute('data-scope');
        populateSkuDropdown();
        updateForecastStudio();
      });
    });

    // Target SKU Select
    const forecastSkuSelect = document.getElementById('forecastSkuSelect');
    if (forecastSkuSelect) {
      forecastSkuSelect.addEventListener('change', () => {
        state.selectedSku = forecastSkuSelect.value;
        updateForecastStudio();
      });
    }

    // 3. Algorithm Engine Family Buttons (Statistical vs ML)
    const modelFamilyBtns = document.querySelectorAll('#modelFamilyGroup .segmented-radio-btn');
    const groupStatisticalAlgorithm = document.getElementById('groupStatisticalAlgorithm');
    const selectStatisticalAlgorithm = document.getElementById('selectStatisticalAlgorithm');
    const groupMlAlgorithm = document.getElementById('groupMlAlgorithm');
    const selectMlAlgorithm = document.getElementById('selectMlAlgorithm');

    modelFamilyBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        modelFamilyBtns.forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        state.selectedFamily = btn.getAttribute('data-family');

        if (state.selectedFamily === 'statistical') {
          if (groupStatisticalAlgorithm) groupStatisticalAlgorithm.style.display = 'flex';
          if (groupMlAlgorithm) groupMlAlgorithm.style.display = 'none';
          if (selectStatisticalAlgorithm) state.selectedModel = selectStatisticalAlgorithm.value;
        } else {
          if (groupStatisticalAlgorithm) groupStatisticalAlgorithm.style.display = 'none';
          if (groupMlAlgorithm) groupMlAlgorithm.style.display = 'flex';
          if (selectMlAlgorithm) state.selectedModel = selectMlAlgorithm.value;
        }
        updateForecastStudio();
      });
    });

    if (selectStatisticalAlgorithm) {
      selectStatisticalAlgorithm.addEventListener('change', () => {
        state.selectedModel = selectStatisticalAlgorithm.value;
        updateForecastStudio();
      });
    }

    if (selectMlAlgorithm) {
      selectMlAlgorithm.addEventListener('change', () => {
        state.selectedModel = selectMlAlgorithm.value;
        updateForecastStudio();
      });
    }

    // 4. Sliders (Horizon & Confidence)
    const sliderHorizon = document.getElementById('sliderHorizon');
    const sliderHorizonVal = document.getElementById('sliderHorizonVal');
    if (sliderHorizon && sliderHorizonVal) {
      sliderHorizon.value = state.selectedHorizon;
      sliderHorizonVal.textContent = state.selectedHorizon;
      sliderHorizon.addEventListener('input', () => {
        sliderHorizonVal.textContent = sliderHorizon.value;
        state.selectedHorizon = parseInt(sliderHorizon.value, 10) || 24;
      });
    }

    const sliderConfidence = document.getElementById('sliderConfidence');
    const sliderConfidenceVal = document.getElementById('sliderConfidenceVal');
    if (sliderConfidence && sliderConfidenceVal) {
      sliderConfidence.value = Math.round(state.selectedConfidence * 100);
      sliderConfidenceVal.textContent = sliderConfidence.value;
      sliderConfidence.addEventListener('input', () => {
        sliderConfidenceVal.textContent = sliderConfidence.value;
        state.selectedConfidence = (parseInt(sliderConfidence.value, 10) || 95) / 100;
      });
    }

    // Action button: Execute Forecast Simulation
    const runForecastBtn = document.getElementById('runForecastBtn');
    if (runForecastBtn) {
      runForecastBtn.addEventListener('click', () => {
        runForecastBtn.innerHTML = '<span>⚡</span> Simulating Horizon...';
        runForecastBtn.disabled = true;
        setTimeout(() => {
          updateForecastStudio();
          runForecastBtn.innerHTML = '<span>🚀</span> Execute Forecast Simulation';
          runForecastBtn.disabled = false;
        }, 180);
      });
    }

    const exportForecastCsvBtn = document.getElementById('exportForecastCsvBtn');
    if (exportForecastCsvBtn) {
      exportForecastCsvBtn.addEventListener('click', exportFilteredForecastCsv);
    }

    updateBranchBadge();
    populateSkuDropdown();
    updateForecastStudio();
  }

  function getFilteredForecastRows() {
    return state.forecastData.filter(row => {
      const matchBranch = (state.selectedBranch === 'ALL' || row.Branch === state.selectedBranch);
      const matchSku = (state.selectedSku === 'ALL' || row.SKU === state.selectedSku);
      return matchBranch && matchSku;
    });
  }

  
